select * from jsonb_populate_recordset(null::public.curated_question_catalog, $questions$[{"id":"8ca15ab2-772b-451f-b13d-68cc1dafce6e","state":"AC","subject":"Noções de Administração","subtopic":"Eficiência, eficácia e efetividade","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Redução de custo por produto entregue indica eficiência. A efetividade depende do impacto real; a eficácia, do alcance das metas.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Eficiência, eficácia e efetividade","question_text":"Uma repartição reduziu o custo por atendimento, mas não melhorou a solução dos problemas dos usuários. A redução de custo indica principalmente:\n\nA) efetividade.\nB) eficácia social.\nC) eficiência.\nD) legalidade.\nE) descentralização.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"C","external_item_key":"pcac-adm-eficiencia-01","import_unique_key":"832944c6b744f6f922bc3f8fc43421e1d3ce8bba7484ec65432ded8319e2d99c","syllabus_topic_id":"adf60b0e-ca40-4c72-94aa-df69eab4afb1","import_content_key":"832944c6b744f6f922bc3f8fc43421e1d3ce8bba7484ec65432ded8319e2d99c","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"2e9e339b-4097-49fb-8dc5-235382cec922","state":"AC","subject":"Noções de Administração","subtopic":"Melhoria contínua","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Check é a verificação dos resultados e a comparação com as metas e padrões.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Melhoria contínua","question_text":"No ciclo PDCA, a etapa Check corresponde a:\n\nA) definir metas e métodos.\nB) executar o plano.\nC) verificar resultados e compará-los com o planejado.\nD) padronizar ou corrigir ações.\nE) extinguir o processo.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"C","external_item_key":"pcac-adm-pdca-01","import_unique_key":"9964be2100c97145dbe4cbad7d35f157c701c1d1625d1f89350c572943772161","syllabus_topic_id":"adf60b0e-ca40-4c72-94aa-df69eab4afb1","import_content_key":"9964be2100c97145dbe4cbad7d35f157c701c1d1625d1f89350c572943772161","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"c10f0347-a545-4f5b-bad2-ba8c4fee9dc2","state":"AC","subject":"Arquivologia","subtopic":"Transferência e recolhimento","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Recolhimento é a passagem ao arquivo permanente; transferência conduz ao intermediário.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Transferência e recolhimento","question_text":"A passagem de documentos do arquivo corrente diretamente para a guarda permanente, em razão de seu valor secundário, denomina-se:\n\nA) transferência.\nB) eliminação.\nC) recolhimento.\nD) expedição.\nE) classificação.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"C","external_item_key":"pcac-arq-destinacao-01","import_unique_key":"88243055895dfcc91bf8978557228e328deea868aeca4049c0204b45b1dcfeff","syllabus_topic_id":"2d81efdc-c368-4a26-a615-e667f7e9f453","import_content_key":"88243055895dfcc91bf8978557228e328deea868aeca4049c0204b45b1dcfeff","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"4520f4b6-a9c3-4051-bab3-5b8c58fb150d","state":"AC","subject":"Arquivologia","subtopic":"Protocolo documental","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Protocolo controla recebimento, registro, classificação, distribuição e tramitação.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Protocolo documental","question_text":"O setor recebe documento, registra sua entrada, classifica e encaminha ao setor responsável, acompanhando sua tramitação. Essas atividades integram:\n\nA) restauração.\nB) protocolo.\nC) recolhimento permanente.\nD) eliminação.\nE) microfilmagem.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"B","external_item_key":"pcac-arq-protocolo-01","import_unique_key":"49c43dd810eea76fa8664740c79e8141cc8c3540a5da45163c822d32675d984f","syllabus_topic_id":"2d81efdc-c368-4a26-a615-e667f7e9f453","import_content_key":"49c43dd810eea76fa8664740c79e8141cc8c3540a5da45163c822d32675d984f","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"02ced9e3-2ea2-4036-9f14-8e1fd27a8c74","state":"AC","subject":"Contabilidade Geral e Análise Financeira","subtopic":"Conciliação","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Conciliação compara fontes e explica diferenças, omissões, duplicidades e divergências de valores ou datas.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Conciliação","question_text":"A conciliação bancária tem como objetivo principal:\n\nA) substituir o extrato por estimativa.\nB) comparar registros bancários e contábeis para identificar diferenças e correspondências.\nC) converter débitos em receitas.\nD) eliminar automaticamente lançamentos antigos.\nE) calcular apenas o lucro líquido.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"B","external_item_key":"pcac-contab-conciliacao-01","import_unique_key":"a689f5ef692917cb61e7c3fceda1adab46ae26f07eee5c1875222ca3a1e7ba35","syllabus_topic_id":"9a3535c6-f720-472a-9138-8acf5f212b31","import_content_key":"a689f5ef692917cb61e7c3fceda1adab46ae26f07eee5c1875222ca3a1e7ba35","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"4fd62829-5c96-44f0-a223-99fe67cb369c","state":"AC","subject":"Contabilidade Geral e Análise Financeira","subtopic":"Movimentação atípica","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O padrão pode ser relevante, mas exige identificação de origem/destino, titularidade, justificativa e contexto. Atipicidade não equivale a prova.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Movimentação atípica","question_text":"Uma conta recebe várias transferências de valores próximos, em sequência, e depois realiza saque. A conclusão inicial mais adequada é:\n\nA) crime comprovado pela repetição.\nB) movimentação que merece análise contextual, sem conclusão automática de ilicitude.\nC) renda tributável em todos os casos.\nD) prova definitiva de lavagem de dinheiro.\nE) operação regular sem necessidade de exame.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"B","external_item_key":"pcac-contab-fracionamento-01","import_unique_key":"5cdb2b413ed0ce65464b2d9fb5ab49726c2c93f197a208e90583ca5887ddf92d","syllabus_topic_id":"9a3535c6-f720-472a-9138-8acf5f212b31","import_content_key":"5cdb2b413ed0ce65464b2d9fb5ab49726c2c93f197a208e90583ca5887ddf92d","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"9ea03932-0d7b-4c53-9dc0-c6bc8a23a219","state":"AC","subject":"Análise de Dados e Informações","subtopic":"Análise temporal","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A linha do tempo descreve sequência e proximidade; causalidade exige análise adicional e exclusão de explicações alternativas.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Análise temporal","question_text":"Dois eventos ocorreram com intervalo de cinco minutos. Essa informação permite concluir, por si só, que o primeiro causou o segundo?\n\nA) Sim, pois ocorreu antes.\nB) Sim, se ambos constarem em registros oficiais.\nC) Não; a proximidade temporal não prova causalidade.\nD) Sim, quando os horários são iguais no mesmo dia.\nE) Não é possível sequer calcular o intervalo.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"C","external_item_key":"pcac-dados-temporal-01","import_unique_key":"6c0c653f4332e8c8558d54a58423c4b85dc1c850a4efb0acd0e4a94f9f791b4d","syllabus_topic_id":"0163395d-da55-4084-bcab-5943d43165b6","import_content_key":"6c0c653f4332e8c8558d54a58423c4b85dc1c850a4efb0acd0e4a94f9f791b4d","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"7a3b8b65-0a08-438b-9548-f204ef0f1504","state":"AC","subject":"Análise de Dados e Informações","subtopic":"Análise de vínculos","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A conexão pode ser representada como indireta por B. Não se deve afirmar relação direta sem registro.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Análise de vínculos","question_text":"Em um diagrama, A se relaciona com B e B se relaciona com C, sem registro de relação direta entre A e C. A relação A-C é:\n\nA) direta e comprovada.\nB) indireta, por intermédio de B.\nC) inexistente em qualquer hipótese.\nD) necessariamente criminosa.\nE) uma relação causal.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"B","external_item_key":"pcac-dados-vinculos-01","import_unique_key":"18044b2bff78c0ab1a1f4019734ce44e79bcfdfaf7865d4b17369ce03e55bb00","syllabus_topic_id":"0163395d-da55-4084-bcab-5943d43165b6","import_content_key":"18044b2bff78c0ab1a1f4019734ce44e79bcfdfaf7865d4b17369ce03e55bb00","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"478d50ea-ad23-482f-9cf7-7e86e4aed160","state":"AC","subject":"Estatística","subtopic":"Probabilidade condicional","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A condição restringe o espaço amostral aos 30 registros noturnos. Assim, 12/30 = 0,4 = 40%.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Probabilidade condicional","question_text":"Em 100 registros, 30 são noturnos e 12 são noturnos com determinado vestígio. Escolhido um registro noturno, a probabilidade de conter o vestígio é:\n\nA) 12%.\nB) 18%.\nC) 30%.\nD) 40%.\nE) 42%.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"D","external_item_key":"pcac-estat-condicional-01","import_unique_key":"81f07a37a95f3a75bd5ed2eb899464de6b52b328b70753806d61cc7495169e76","syllabus_topic_id":"dcf59d51-2edf-4244-afc3-9cc5c43b17ba","import_content_key":"81f07a37a95f3a75bd5ed2eb899464de6b52b328b70753806d61cc7495169e76","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"03edeb73-0926-4e62-aafc-9fa086a39b41","state":"AC","subject":"Estatística","subtopic":"União de eventos","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"P(A∪B)=P(A)+P(B)−P(A∩B)=0,5+0,4−0,2=0,7.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"União de eventos","question_text":"Se P(A)=0,5, P(B)=0,4 e P(A∩B)=0,2, então P(A∪B) é:\n\nA) 0,2.\nB) 0,5.\nC) 0,7.\nD) 0,9.\nE) 1,1.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"C","external_item_key":"pcac-estat-uniao-01","import_unique_key":"17e87469b8ad965673f7f6b5138fd61c42a1ca7a44d85aeb6ab6b12c164d01b7","syllabus_topic_id":"dcf59d51-2edf-4244-afc3-9cc5c43b17ba","import_content_key":"17e87469b8ad965673f7f6b5138fd61c42a1ca7a44d85aeb6ab6b12c164d01b7","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"5ceb6971-882b-4e8c-a5aa-493675ba154e","state":"AC","subject":"Tecnologia da Informação e Segurança da Informação","subtopic":"Serviços de rede","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"DNS traduz o nome de domínio em endereço IP.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Serviços de rede","question_text":"Ao digitar um domínio no navegador, o serviço que normalmente localiza o endereço IP correspondente é:\n\nA) DHCP.\nB) DNS.\nC) SMTP.\nD) FTP.\nE) NAT.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"B","external_item_key":"pcac-ti-dns-01","import_unique_key":"ae663b3754eb578d284b28b04facab518febade53fb0ac551891bd03189943ac","syllabus_topic_id":"d692262e-e7fc-4472-a41c-6e2918c70ccc","import_content_key":"ae663b3754eb578d284b28b04facab518febade53fb0ac551891bd03189943ac","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"8811247b-6021-4572-a40b-2268664ee245","state":"AC","subject":"Tecnologia da Informação e Segurança da Informação","subtopic":"Protocolos de transporte","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:36:34.358389+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"TCP é orientado à conexão e oferece mecanismos de confiabilidade e ordenação. UDP é mais simples e não garante entrega ou ordem pelo próprio protocolo.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:36:34.358389+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Protocolos de transporte","question_text":"Sobre TCP e UDP, assinale a alternativa correta:\n\nA) UDP garante entrega ordenada por definição.\nB) TCP não possui controle de fluxo.\nC) TCP oferece mecanismos de confiabilidade e ordenação; UDP não garante esses recursos por si só.\nD) Ambos são protocolos de resolução de nomes.\nE) TCP e UDP são serviços de atribuição automática de IP.","content_status":"active","career_category":"conhecimentos específicos","official_answer":"C","external_item_key":"pcac-ti-tcpudp-01","import_unique_key":"3aaa9325f173c6b5e21c906dae5022217245e9e9346752039d676917b3c29bea","syllabus_topic_id":"d692262e-e7fc-4472-a41c-6e2918c70ccc","import_content_key":"3aaa9325f173c6b5e21c906dae5022217245e9e9346752039d676917b3c29bea","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null}]$questions$::jsonb)
